// FortreeCity_House2 (zone 137): generated by converter/gen_interior_recipes_houses.py (Sapphire's simple people, signs
// and furniture messages). Messages: src/text/script/0156_room_FortreeCity_House2.txt
#include "asm/field_script.inc"
#include "hoenn.h"  // ch7
#include "hoenn_story.inc"  // ch7

    ScriptEntry Script_None
    ScriptEntry FH2_HiddenPowerGiver  // 2: FortreeCity_House2_EventScript_HiddenPowerGiver  // story:
    ScriptEntriesEnd

Script_None:
    VMHalt
    .balign 4, 0

// ---- story (chapter Ch7, ch7 agent 2026-10-07; Sapphire data/maps/FortreeCity_House2/scripts.inc; generators must keep
// everything from this line on). Script 2, text lines 1-10 (line 0 is the generator's). The old woman (uid 1) is in
// data/story/ch7.json. Room tiles = Sapphire tiles + (1,1).
#include "scenes/ch7_lib.inc"
#define T_Greeting 1
#define T_CoinInWhichHand 2
#define T_Correct1 3
#define T_Correct2 4
#define T_Awoken 5
#define T_Explain 6
#define T_Wrong 7
#define T_BagFull 8
#define T_Right 9
#define T_Left 10
#define FH2_GUESS 0x803E                            // the menu's result: Sapphire's multichoice 54 (Right 0, Left 1)

    .macro fh2_ask n                                // msgbox n + multichoice 21, 8, 54, 1 (Black 2's list menu; B is ignored)
    ParentActorMsg MSGFILE_SCRIPT, \n, 0, 0
    ListMenu_AnchorTopRight 31, 7, 0, 0, FH2_GUESS
    ListMenuAdd T_Right, 65535, 0
    ListMenuAdd T_Left, 65535, 1
    ListMenuShow
    MsgWinCloseAll
    .endm

FH2_HiddenPowerGiver:                               // FortreeCity_House2_EventScript_HiddenPowerGiver
    c7_talk
    h_goto_if_set FLAG_RECEIVED_TM10, L_FH2_ExplainHiddenPower
    h_goto_if_set FLAG_MET_HIDDEN_POWER_GIVER, L_FH2_Question
    h_msgbox T_Greeting                             // People... Pokémon... Their hidden powers are aroused by ...
    h_setflag FLAG_MET_HIDDEN_POWER_GIVER
L_FH2_Question:
    fh2_ask T_CoinInWhichHand                       // Let this old woman see if your hidden power has awoken... right or left?
    h_goto_if_eq FH2_GUESS, 1, L_FH2_WrongGuess     // (the right answers: Right, Right, Left)
    fh2_ask T_Correct1                              // Oh! Yes, correct! We shall try again. ...
    h_goto_if_eq FH2_GUESS, 1, L_FH2_WrongGuess
    fh2_ask T_Correct2                              // Oh! Yes, correct again! We shall try once more. ...
    h_goto_if_eq FH2_GUESS, 0, L_FH2_WrongGuess
    h_msgbox T_Awoken                               // Oh! Splendid! Your hidden power has awoken! Here, take this ...
    h_closemessage                                  // (Black 2's item script opens its own window)
    h_giveitem ITEM_TM10                            // TM10 is Hidden Power in Black 2 too
    h_goto_if_eq HLIB_RESULT, 0, L_FH2_BagFull
    h_setflag FLAG_RECEIVED_TM10
    h_msgbox T_Explain                              // Hidden Power is a move that changes with the Pokémon.
    h_release
L_FH2_ExplainHiddenPower:
    h_msgbox T_Explain
    h_release
L_FH2_WrongGuess:
    h_msgbox T_Wrong                                // No, too bad. You guessed wrong.
    h_release
L_FH2_BagFull:                                      // Common_EventScript_ShowBagIsFull
    h_bag_is_full T_BagFull
    h_release
    .balign 4, 0
